// @FIGURE_CODE_BEGIN
/* ── Element spec (one line per drawn element) ────────────────────────────
   x axis        → Line black #111 origin→3.0 along figure +x  + ConeGeometry(0.075,0.24) tip
   y axis        → Line black #111 origin→3.0 along figure +y  + cone tip
   z axis        → Line black #111 origin→3.0 along figure +z  + cone tip
   cube edges    → LineSegments + LineDashedMaterial #E8642A (dash .12 / gap .10),
                   9 edges (the 3 axis-coincident ones are the solid black axes)
   ions m1..m8   → Mesh SphereGeometry(0.22,32,24) MeshStandardMaterial
                   green #7CB342 / red #C0392B, key light upper-left + ambient fill
   hover guides  → LineSegments dashed grey #8A8A8A from ion to its 3 axis feet
   labels        → addLabel HTML: '0', italic x/y/z, m<sub>i</sub> (+ coords in mass mode)
   ─────────────────────────────────────────────────────────────────────── */

const a = 2.0;
// figure coords (x → screen lower-right, y → screen upper-right, z → screen up)
// map to world:  world = (fx, fz, -fy)
const P = (fx, fy, fz) => new THREE.Vector3(fx, fz, -fy);

/* ── Lights ──────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.60));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.90);
keyLight.position.set(-3, 6, 5);          // upper-left key
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.25);
fillLight.position.set(5, -2, -5);
scene.add(fillLight);

const AXIS_COLOR = 0x111111;

/* ── Axes with arrowheads ────────────────────────────────────────────── */
const axisLen = 3.0;
const axisDirs = [
  { dir: P(1, 0, 0), label: '<i>x</i>', tip: P(axisLen, 0, 0), loff: [14, 13] },
  { dir: P(0, 1, 0), label: '<i>y</i>', tip: P(0, axisLen, 0), loff: [17, -11] },
  { dir: P(0, 0, 1), label: '<i>z</i>', tip: P(0, 0, axisLen), loff: [-3, -19] }
];
const axisMat = new THREE.LineBasicMaterial({ color: AXIS_COLOR });
const coneMat = new THREE.MeshBasicMaterial({ color: AXIS_COLOR });
const UPY = new THREE.Vector3(0, 1, 0);

for (const ax of axisDirs) {
  const end = ax.dir.clone().multiplyScalar(axisLen);
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), end]),
    axisMat
  );
  line.renderOrder = 3;
  scene.add(line);

  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.24, 20), coneMat);
  cone.position.copy(end);
  cone.quaternion.setFromUnitVectors(UPY, ax.dir.clone().normalize());
  scene.add(cone);
}

/* ── Dashed cube edges ───────────────────────────────────────────────── */
const corners = [];
for (let i = 0; i < 2; i++)
  for (let j = 0; j < 2; j++)
    for (let k = 0; k < 2; k++) corners.push([i, j, k]);

const edgePts = [];
for (let p = 0; p < corners.length; p++) {
  for (let q = p + 1; q < corners.length; q++) {
    const A = corners[p], B = corners[q];
    const diff = Math.abs(A[0] - B[0]) + Math.abs(A[1] - B[1]) + Math.abs(A[2] - B[2]);
    if (diff !== 1) continue;
    // the three edges lying on the axes are drawn solid black instead
    const touchesOrigin = (A[0] + A[1] + A[2] === 0) || (B[0] + B[1] + B[2] === 0);
    if (touchesOrigin) continue;
    edgePts.push(P(A[0] * a, A[1] * a, A[2] * a), P(B[0] * a, B[1] * a, B[2] * a));
  }
}
const edgeGeom = new THREE.BufferGeometry().setFromPoints(edgePts);
const edgeMat = new THREE.LineDashedMaterial({
  color: 0xE8642A, dashSize: 0.12, gapSize: 0.10
});
const cubeEdges = new THREE.LineSegments(edgeGeom, edgeMat);
cubeEdges.computeLineDistances();
scene.add(cubeEdges);

/* ── Ions ────────────────────────────────────────────────────────────── */
const GREEN = 0x7CB342, RED = 0xC0392B;
const GREEN_N = 0x9FB0C0, RED_N = 0x7E8C9E;

// offsets follow the printed figure: m1 below-left, m2 below, m3 right,
// m4 right, m5 left, m6 lower-right, m7 upper-right, m8 above.
const IONS = [
  { i: 1, c: [0, 0, 0], g: 'green', off: [-6, 27],  coord: '(0, 0, 0)' },
  { i: 2, c: [1, 0, 0], g: 'red',   off: [0, 29],   coord: '(<i>a</i>, 0, 0)' },
  { i: 3, c: [1, 1, 0], g: 'green', off: [29, 7],   coord: '(<i>a</i>, <i>a</i>, 0)' },
  { i: 4, c: [0, 1, 0], g: 'red',   off: [28, -9],  coord: '(0, <i>a</i>, 0)' },
  { i: 5, c: [0, 0, 1], g: 'red',   off: [-29, 3],  coord: '(0, 0, <i>a</i>)' },
  { i: 6, c: [1, 0, 1], g: 'green', off: [29, 19],  coord: '(<i>a</i>, 0, <i>a</i>)' },
  { i: 7, c: [1, 1, 1], g: 'red',   off: [24, -23], coord: '(<i>a</i>, <i>a</i>, <i>a</i>)' },
  { i: 8, c: [0, 1, 1], g: 'green', off: [0, -29],  coord: '(0, <i>a</i>, <i>a</i>)' }
];

const sphereGeom = new THREE.SphereGeometry(0.22, 32, 24);
const ions = [];

for (const spec of IONS) {
  const pos = P(spec.c[0] * a, spec.c[1] * a, spec.c[2] * a);
  const base = spec.g === 'green' ? GREEN : RED;
  const mat = new THREE.MeshStandardMaterial({
    color: base, roughness: 0.36, metalness: 0.08,
    emissive: new THREE.Color(0x000000)
  });
  const mesh = new THREE.Mesh(sphereGeom, mat);
  mesh.position.copy(pos);
  mesh.renderOrder = 4;
  scene.add(mesh);

  const plain = spec.coord.replace(/<\/?i>/g, '');
  const ion = { ...spec, pos, mesh, mat, base, neutral: spec.g === 'green' ? GREEN_N : RED_N, plain };
  ions.push(ion);

  const groupTxt = spec.g === 'green'
    ? 'green ion species (with m\u2081, m\u2083, m\u2086, m\u2088)'
    : 'red ion species (with m\u2082, m\u2084, m\u2085, m\u2087)';
  registerInteractive(mesh, {
    title: `m${spec.i} at ${plain}`,
    tooltip: `m${spec.i} \u2014 ${plain} \u2014 ${spec.g} ion`,
    body: `Mass m<sub>${spec.i}</sub> sits at the cube corner ${plain}, with coordinates written in units of the edge length a. It belongs to the ${groupTxt}. Because ions alternate along every edge, none of its three nearest corner neighbours has the same colour. Feeding all eight positions into R = (\u03A3 m\u1D62 r\u1D62)/(\u03A3 m\u1D62) gives the centre of mass of the cell \u2014 (a/2, a/2, a/2) when the eight masses are equal.`
  });
}

/* ── Hover guide lines to the axes ───────────────────────────────────── */
const guideMat = new THREE.LineDashedMaterial({
  color: 0x8A8A8A, dashSize: 0.09, gapSize: 0.07, transparent: true, opacity: 0.9
});
const guides = new THREE.LineSegments(new THREE.BufferGeometry(), guideMat);
guides.visible = false;
scene.add(guides);

function showGuides(ion) {
  const pts = [
    ion.pos, P(ion.c[0] * a, 0, 0),
    ion.pos, P(0, ion.c[1] * a, 0),
    ion.pos, P(0, 0, ion.c[2] * a)
  ];
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  const old = guides.geometry;
  guides.geometry = g;
  old?.dispose?.();
  guides.computeLineDistances();
  guides.visible = true;
}

/* ── Camera (after all geometry) ─────────────────────────────────────────
   Axis screen angles measured off the source drawing: the x axis leaves the
   origin only ~8 deg below horizontal and the y axis ~37 deg above it.  That
   flat, wide pose (az ~66.6, elev ~19) is NOT isometric, so no pair of corner
   ions projects on top of another (the isometric default collapsed m4 onto
   m6).                                                                      */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 8, z: 37 },
  rollDeg: 0,
  heightFraction: 0.78
});
document.getElementById('btnReset').style.display = '';

/* ── Labels ──────────────────────────────────────────────────────────── */
addLabel('0', P(0, 0, 0), { fontSize: '16px', offset: [-27, 3], bold: true });
for (const ax of axisDirs) {
  addLabel(ax.label, ax.tip, { fontSize: '17px', bold: true, offset: ax.loff });
}
for (const ion of ions) {
  ion.label = addLabel(`m<sub>${ion.i}</sub>`, ion.pos, {
    fontSize: '15px', offset: ion.off
  });
}

/* ── Display mode ────────────────────────────────────────────────────── */
let massMode = false;
const btnIon = document.getElementById('btnIon');
const btnMass = document.getElementById('btnMass');

function refreshLabels() {
  for (const ion of ions) {
    ion.label.div.innerHTML = massMode
      ? `m<sub>${ion.i}</sub><br><span style="font-size:10px;color:#41586e">${ion.coord}</span>`
      : `m<sub>${ion.i}</sub>`;
  }
}

function setMode(mode) {
  massMode = (mode === 'mass');
  for (const ion of ions) ion.mat.color.setHex(massMode ? ion.neutral : ion.base);
  refreshLabels();
  btnIon.classList.toggle('active', !massMode);
  btnMass.classList.toggle('active', massMode);
}
btnIon.addEventListener('click', () => setMode('ion'));
btnMass.addEventListener('click', () => setMode('mass'));
setMode('ion');

/* ── Hover visuals (tooltip handled by the scaffold) ─────────────────── */
const hoverRay = new THREE.Raycaster();
const hoverPt = new THREE.Vector2();
let hovered = null;

canvas.addEventListener('pointermove', (e) => {
  const r = canvas.getBoundingClientRect();
  hoverPt.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  hoverPt.y = -((e.clientY - r.top) / r.height) * 2 + 1;
  hoverRay.setFromCamera(hoverPt, camera);
  const hits = hoverRay.intersectObjects(ions.map(i => i.mesh), false);
  const next = hits.length ? ions.find(i => i.mesh === hits[0].object) : null;
  if (next === hovered) return;
  if (hovered) hovered.mat.emissive.setHex(0x000000);
  hovered = next || null;
  if (hovered) {
    hovered.mat.emissive.setHex(0x554400);
    showGuides(hovered);
  } else {
    guides.visible = false;
  }
});
canvas.addEventListener('pointerleave', () => {
  if (hovered) hovered.mat.emissive.setHex(0x000000);
  hovered = null;
  guides.visible = false;
});

/* ── Guided demo ─────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: '1. The unit cell on the axes',
    text: 'A cube of edge a sits with one corner at the origin, its edges running along x, y and z. Dashed orange lines outline the cell.',
    mode: 'ion', pulse: false
  },
  {
    title: '2. Alternating ions',
    text: 'Green and red spheres alternate around every face: m\u2081, m\u2083, m\u2086 and m\u2088 are one species, m\u2082, m\u2084, m\u2085 and m\u2087 the other. No two like-coloured ions ever share an edge \u2014 drag to orbit and check it in all three directions.',
    mode: 'ion', pulse: true
  },
  {
    title: '3. Eight masses with coordinates',
    text: 'Now the same corners read as numbered masses m\u2081\u2013m\u2088 with coordinates (0,0,0), (a,0,0), (a,a,0), (0,a,0), (0,0,a), (a,0,a), (a,a,a), (0,a,a) \u2014 the data for R = (\u03A3 m\u1D62 r\u1D62)/(\u03A3 m\u1D62).',
    mode: 'mass', pulse: false
  }
];
let stepIdx = 0;
let pulseOn = false;
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

function goToStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  const s = STEPS[stepIdx];
  setMode(s.mode);
  pulseOn = s.pulse;
  stepTitle.textContent = s.title;
  stepText.textContent = s.text;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);

/* ── Local animation loop for pulse / hover scaling ──────────────────── */
(function tick() {
  requestAnimationFrame(tick);
  const t = performance.now() / 1000;
  for (const ion of ions) {
    let sc = 1;
    if (pulseOn) sc *= 1 + 0.10 * Math.sin(t * 2.2 + (ion.g === 'green' ? 0 : Math.PI));
    if (ion === hovered) sc *= 1.25;
    ion.mesh.scale.setScalar(sc);
  }
})();
