});

/* ── Camera (after all geometry) ─────────────────────────────────────────
   Orthographic axonometric pose. Axis screen angles chosen to match the flat
   drafting look of the source (x barely below horizontal, y a good way above
   it) while keeping the y direction long enough on screen that its arrowhead
   and the m4 sphere stay well apart.                                        */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 12, z: 30 },
  rollDeg: 0,
  heightFraction: 0.62
});
document.getElementById('btnReset').style.display = '';

/* ── Labels ──────────────────────────────────────────────────────────── */
function halo(entry) {
  entry.div.style.textShadow =
    '0 0 3px #fff, 0 0 3px #fff, 0 0 5px #fff';
  return entry;
}

halo(addLabel('0', new THREE.Vector3(0, 0, 0),
  { fontSize: '18px', offset: [-34, 6], bold: true }));
for (const ax of axisDirs) {
  halo(addLabel(ax.label, ax.tip, { fontSize: '19px', bold: true, offset: ax.loff }));
}
for (const ion of ions) {
  ion.label = halo(addLabel(`m<sub>${ion.i}</sub>`, ion.pos, {
    fontSize: '17px', offset: ion.off
  }));
}
const cmLabel = halo(addLabel(
  '<i>R</i>', cmPos, { fontSize: '16px', bold: true, color: '#1d3f78', offset: [26, -20] }));
cmLabel.div.style.display = 'none';

/* ── Display mode ────────────────────────────────────────────────────── */
let massMode = false;
const btnIon = document.getElementById('btnIon');
const btnMass = document.getElementById('btnMass');

function refreshLabels() {
  for (const ion of ions) {
    ion.label.div.innerHTML = massMode
      ? `m<sub>${ion.i}</sub><br><span style="font-size:11px;color:#41586e">${ion.coord}</span>`
      : `m<sub>${ion.i}</sub>`;
  }
}

function setMode(mode) {
  massMode = (mode === 'mass');
  for (const ion of ions) ion.mat.color.setHex(massMode ? ion.neutral : ion.base);
  edgeMat.opacity = 1;
  refreshLabels();
  btnIon.classList.toggle('active', !massMode);
  btnMass.classList.toggle('active', massMode);
}
btnIon.addEventListener('click', () => setMode('ion'));
btnMass.addEventListener('click', () => setMode('mass'));
setMode('ion');

/* ── Centre-of-mass toggle ───────────────────────────────────────────── */
const chkCM = document.getElementById('chkCM');
chkCM.addEventListener('change', () => {
  cmGroup.visible = chkCM.checked;
  cmLabel.div.style.display = chkCM.checked ? '' : 'none';
});

/* ── Hover visuals (tooltip handled by the scaffold) ─────────────────── */
const hoverRay = new THREE.Raycaster();
const hoverPt = new THREE.Vector2();
let hovered = null;

canvas.addEventListener('pointermove', (e) => {
  const r = canvas.getBoundingClientRect();
  hoverPt.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  hoverPt.y = -((e.clientY - r.top) / r.height) * 2 + 1;
  hoverRay.setFromCamera(hoverPt, camera);
  const hits = hoverRay.intersectObjects(ions.map(i => i.mesh), false);
  const next = hits.length ? ions.find(i => i.mesh === hits[0].object) : null;
  if (next === hovered) return;
  if (hovered) {
    hovered.mat.emissive.setHex(0x000000);
    hovered.label.div.style.fontWeight = '';
  }
  hovered = next || null;
  if (hovered) {
    hovered.mat.emissive.setHex(0x554400);
    hovered.label.div.style.fontWeight = '700';
    showGuides(hovered);
  } else {
    guides.visible = false;
  }
});
canvas.addEventListener('pointerleave', () => {
  if (hovered) {
    hovered.mat.emissive.setHex(0x000000);
    hovered.label.div.style.fontWeight = '';
  }
  hovered = null;
  guides.visible = false;
});

/* ── Guided demo ─────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'The unit cell on the axes',
    text: 'A cube of edge a sits with one corner at the origin, its edges running along x, y and z. Dashed orange lines outline the cell; the three edges on the axes are overdrawn by the solid black axis lines.',
    mode: 'ion', pulse: false
  },
  {
    title: 'Alternating ions',
    text: 'Green and red spheres alternate around every face: m\u2081, m\u2083, m\u2086 and m\u2088 are one species, m\u2082, m\u2084, m\u2085 and m\u2087 the other. No two like-coloured ions ever share an edge \u2014 drag to orbit and check it in all three directions.',
    mode: 'ion', pulse: true
  },
  {
    title: 'Eight masses with coordinates',
    text: 'Now the same corners read as numbered masses m\u2081\u2013m\u2088 with coordinates (0,0,0), (a,0,0), (a,a,0), (0,a,0), (0,0,a), (a,0,a), (a,a,a), (0,a,a) \u2014 the data for R = (\u03A3 m\u1D62 r\u1D62)/(\u03A3 m\u1D62). Tick the box above to see where R lands for equal masses.',
    mode: 'mass', pulse: false
  }
];
let stepIdx = 0;
let pulseOn = false;
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');
const stepCount = document.getElementById('stepCount');
const btnPrev = document.getElementById('btnPrev');
const btnNext = document.getElementById('btnNext');

function goToStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  const s = STEPS[stepIdx];
  setMode(s.mode);
  pulseOn = s.pulse;
  stepCount.textContent = `Step ${stepIdx + 1} of ${STEPS.length}`;
  stepTitle.textContent = `${stepIdx + 1}. ${s.title}`;
  stepText.textContent = s.text;
  btnPrev.disabled = stepIdx === 0;
  btnNext.disabled = stepIdx === STEPS.length - 1;
}
btnPrev.addEventListener('click', () => goToStep(stepIdx - 1));
btnNext.addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);

/* ── Local animation loop for pulse / hover scaling ──────────────────── */
(function tick() {
  requestAnimationFrame(tick);
  const t = performance.now() / 1000;
  for (const ion of ions) {
    let sc = 1;
    if (pulseOn) sc *= 1 + 0.09 * Math.sin(t * 2.2 + (ion.g === 'green' ? 0 : Math.PI));
    if (ion === hovered) sc *= 1.25;
    ion.mesh.scale.setScalar(sc);
  }
})();
